import React, { useState } from 'react';
import axios from 'axios';

const Login = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [formData, setFormData] = useState({ username: '', email: '', password: '' });

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const endpoint = isRegister ? '/auth/register' : '/auth/login';
      const res = await axios.post(endpoint, formData);
      onLogin(res.data);
    } catch (err) {
      alert(err.response?.data?.msg || 'Error occurred');
    }
  };

  return (
    <div style={{ maxWidth: '350px', margin: '80px auto', padding: '40px 20px', border: '1px solid #dbdbdb', background: '#fff', borderRadius: '8px' }}>
      <h1 style={{ fontFamily: 'cursive', textAlign: 'center', fontSize: '3rem', marginBottom: '20px', color: '#262626' }}>Nipix</h1>
      <form onSubmit={handleSubmit}>
        {isRegister && <input type="text" placeholder="Username" value={formData.username} onChange={e => setFormData({...formData, username: e.target.value})} required style={{ width: '100%', padding: '10px', margin: '8px 0', border: '1px solid #dbdbdb', borderRadius: '6px', boxSizing: 'border-box' }} />}
        <input type="email" placeholder="Email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} required style={{ width: '100%', padding: '10px', margin: '8px 0', border: '1px solid #dbdbdb', borderRadius: '6px', boxSizing: 'border-box' }} />
        <input type="password" placeholder="Password" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} required style={{ width: '100%', padding: '10px', margin: '8px 0', border: '1px solid #dbdbdb', borderRadius: '6px', boxSizing: 'border-box' }} />
        <button type="submit" style={{ width: '100%', padding: '10px', background: '#0095f6', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600', marginTop: '10px' }}>{isRegister ? 'Sign Up for Nipix' : 'Log In'}</button>
      </form>
      <div style={{ textAlign: 'center', marginTop: '25px', borderTop: '1px solid #efefef', paddingTop: '20px' }}>
        {isRegister ? 'Have an account?' : "Don't have an account?"} 
        <span onClick={() => setIsRegister(!isRegister)} style={{ color: '#0095f6', cursor: 'pointer', marginLeft: '5px', fontWeight: '600' }}>{isRegister ? 'Log In' : 'Sign Up'}</span>
      </div>
    </div>
  );
};

export default Login;
